from lib import *
CAT={'Lunas':('cg','wallet'),'Absensi':('cb','checkc'),'Role':('cy','users'),'Hapus':('cr','trash')}
def it(cat,who,act,det,t,sel=False):
    c,ic=CAT[cat]
    return f'<div class="card" style="padding:8px 10px;margin-bottom:6px"><div class="row" style="align-items:flex-start;gap:9px"><div class="ic" style="width:30px;height:30px;font-size:13px;background:{"#DDF1E5" if cat=="Lunas" else "#DCE6FA" if cat=="Absensi" else "#FFEBA8" if cat=="Role" else "#FADCDF"}">[[{ic}]]</div><div style="flex:1;min-width:0"><div class="row sp"><span class="t1" style="font-size:11.5px">{act}</span><span class="chip {c}">{cat}</span></div><div class="t2" style="color:#1C1B1F;margin-top:1px">{det}</div><div class="t3" style="margin-top:2px">{who} • {t}</div></div></div></div>'
def day(d): return f'<div class="t3" style="font-weight:600;margin:8px 2px 4px;letter-spacing:.3px">{d}</div>'
def chips(sel,items=('Semua','Lunas','Absensi','Role','Hapus')):
    return '<div class="row" style="gap:5px;margin-bottom:6px">'+''.join(f'<span class="chip" style="padding:3px 10px;{"background:#FFC928;border:1.5px solid #1C1B1F;color:#1C1B1F" if i==sel else "background:#fff;border:1px solid #EADFC2;color:#6B6458"}">{x}</span>' for i,x in enumerate(items))+'</div>'
SRCH='<div class="row" style="gap:8px;margin-bottom:8px"><div class="inp row" style="flex:1;gap:7px;padding:8px 11px;color:#6B6458"><span>[[search]]</span><span>Cari pelaku atau data…</span></div><div class="ic" style="border:1.5px solid #1C1B1F;background:#FFC928;width:36px;height:36px;border-radius:12px">[[filter]]</div></div>'
LIST=(it('Lunas','Aisyah Putri','Menandai lunas: Hana Safitri','Kas Minggu ke-1 Nov • Rp6.000 • Tunai','10.05')+it('Lunas','Aisyah Putri','Menandai lunas: Bima Sakti','Kas Minggu ke-1 Nov • Rp6.000 • Transfer','09.12')+it('Lunas','Aisyah Putri','Menandai lunas: Gita Nuraini','Kas Minggu ke-1 Nov • Rp6.000 • QRIS','08.40')+it('Absensi','Ahmad Ramadhan','Menyimpan absensi IX-H','Hadir 28 • Izin 2 • Sakit 1 • Alpha 1','07.58'))
s1=phone('1. Log Aktivitas',bar('Log Aktivitas','<span class="chip cb">Admin</span>')+SRCH+chips(0)+day('RABU, 4 NOVEMBER 2026')+LIST+day('SELASA, 3 NOVEMBER 2026')+it('Role','Ahmad Ramadhan','Mengubah role: Aisyah Putri','Siswa → Pengurus (Bendahara)','16.20'),nav=None)
def sec(t): return f'<div class="t1" style="margin:10px 0 5px;font-size:11.5px">{t}</div>'
def ch(x,on=False): return f'<span class="chip" style="padding:4px 11px;margin:0 4px 4px 0;{"background:#FFC928;border:1.5px solid #1C1B1F;color:#1C1B1F" if on else "background:#fff;border:1px solid #EADFC2;color:#6B6458"}">{x}</span>'
def cb(x,on): return f'<div class="row" style="gap:8px;margin:5px 0"><span style="width:16px;height:16px;border-radius:5px;display:flex;align-items:center;justify-content:center;font-size:10px;{"background:#FFC928;border:2px solid #1C1B1F" if on else "background:#fff;border:1.5px solid #EADFC2"}">{"[[check]]" if on else ""}</span><span class="t2" style="color:#1C1B1F">{x}</span></div>'
s2=phone('2. Filter',bar('Log Aktivitas')+SRCH+chips(0)+day('RABU, 4 NOVEMBER 2026')+LIST[:600] if False else bar('Log Aktivitas')+SRCH+day('RABU, 4 NOVEMBER 2026')+it('Lunas','Aisyah Putri','Menandai lunas: Hana Safitri','Kas Minggu ke-1 Nov • Rp6.000 • Tunai','10.05'),over=f'''<div class="dim"></div><div class="sheet"><div style="width:36px;height:4px;border-radius:2px;background:#EADFC2;margin:0 auto 8px"></div><div class="row sp"><b style="font-size:14px">Filter Log</b><span class="t2">Atur ulang</span></div>{sec("Pengguna")}<div>{ch("Semua")}{ch("Ahmad Ramadhan",True)}{ch("Aisyah Putri",True)}</div>{sec("Tanggal")}<div>{ch("Hari ini")}{ch("7 hari")}{ch("Kustom",True)}</div><div class="inp row sp" style="margin-top:2px;font-size:11px"><span class="row" style="gap:7px">[[cal]] 2 Nov – 4 Nov 2026</span><span style="color:#6B6458">[[chev]]</span></div>{sec("Jenis aktivitas")}{cb("Tandai lunas",True)}{cb("Absensi",True)}{cb("Ubah role",True)}{cb("Hapus data",True)}<div class="btn pri" style="margin-top:10px">Terapkan (6 hasil)</div></div>''')
def kv(k,v,c=''): return f'<div class="row sp" style="padding:6px 0;border-bottom:1px solid #F1E8CF"><span class="t2">{k}</span><b style="font-size:11px;text-align:right;{c}">{v}</b></div>'
s3=phone('3. Detail Entri',bar('Detail Aktivitas')+'<div class="card"><div class="row" style="gap:10px"><div class="ic" style="background:#FFEBA8">[[users]]</div><div><div class="t1">Mengubah role pengguna</div><span class="chip cy" style="margin-top:3px">Role</span></div></div></div><div class="card" style="padding:4px 12px">'+kv('Pelaku','Ahmad Ramadhan (Admin)')+kv('Pengguna','Aisyah Putri')+kv('Waktu','Sel, 3 Nov 2026 • 16.20 WIB')+kv('Perangkat','Redmi 9A • Android')+'</div><div class="t1" style="margin:8px 2px 5px">Perubahan</div><div class="card"><div class="row sp"><div style="text-align:center;flex:1"><div class="t3">Sebelum</div><span class="chip cx" style="margin-top:4px">Siswa</span></div><span style="color:#6B6458">[[arrow]]</span><div style="text-align:center;flex:1"><div class="t3">Sesudah</div><span class="chip cy" style="margin-top:4px">Pengurus (Bendahara)</span></div></div></div><div class="card"><div class="t3">Alasan</div><div class="t1" style="font-weight:500">Ditunjuk sebagai bendahara kelas IX-H</div></div><div class="al ab"><span>[[lock]]</span><span>Log bersifat permanen: tidak bisa diubah atau dihapus, bahkan oleh Admin.</span></div><div class="btn sec">[[download]] Ekspor Entri (PDF)</div>')
s4=phone('4. Hasil Kosong',bar('Log Aktivitas')+SRCH+'<div class="row" style="gap:5px;margin-bottom:6px"><span class="chip cx" style="background:#FFEBA8;color:#1C1B1F;padding:3px 10px">Eka Wijaya [[x]]</span><span class="chip cx" style="background:#FFEBA8;color:#1C1B1F;padding:3px 10px">Hari ini [[x]]</span></div>'+f'<div style="text-align:center;margin-top:60px">{blob("sleep",120)}<div style="font-weight:700;font-size:14px;margin-top:6px">Tidak ada aktivitas</div><div class="t2" style="padding:0 26px;margin-top:4px">Belum ada catatan untuk filter ini. Coba ubah pengguna atau rentang tanggal.</div></div><div class="btn sec" style="margin-top:60px">Atur Ulang Filter</div>')
s5=phone('5. Gagal Memuat',bar('Log Aktivitas')+f'<div style="text-align:center;margin-top:36px">{blob("sad",120)}<div style="font-weight:700;font-size:14px;margin-top:6px">Log gagal dimuat</div><div class="t2" style="padding:0 24px;margin-top:4px">Periksa koneksi internetmu, lalu coba lagi.</div></div><div class="al ay" style="margin-top:22px"><span>[[wifioff]]</span><span>Offline. Menampilkan data tersimpan terakhir pukul 08.45 WIB.</span></div><div class="btn pri">[[refresh]] Coba Lagi</div><div class="btn sec">Lihat Data Tersimpan</div>')
s6=phone('6. Akses Pengurus',bar('Log Aktivitas','<span class="chip cy">Pengurus</span>')+f'<div style="text-align:center;margin-top:50px"><div class="ic" style="width:64px;height:64px;margin:0 auto;font-size:26px;background:#FFEBA8;border:2px solid #1C1B1F">[[lock]]</div><div style="font-weight:700;font-size:14px;margin-top:10px">Khusus Admin</div><div class="t2" style="padding:0 26px;margin-top:4px">Log aktivitas hanya bisa dilihat oleh Admin kelas. Hubungi Ahmad Ramadhan bila perlu riwayat.</div></div><div class="btn pri" style="margin-top:50px">Kembali ke Beranda</div>')
R_=rules(['Log Aktivitas <b>hanya untuk Admin</b>; Pengurus dan Siswa tidak bisa membukanya.','Dicatat otomatis: <b>tandai lunas</b> (siswa, nominal, metode), <b>absensi</b>, <b>ubah role</b>, dan <b>hapus data</b>.','Tiap entri memuat pelaku, waktu WIB, perangkat, dan perubahan sebelum/sesudah.','Log <b>permanen</b>: tidak bisa diubah atau dihapus, bahkan oleh Admin.','Filter per <b>pengguna</b>, <b>tanggal</b>, dan <b>jenis</b>; hasil kosong dan gagal memuat punya layar sendiri.','Saat offline, data tersimpan terakhir tetap bisa dilihat; ekspor entri ke PDF.','Diarsipkan saat pergantian semester (27); akses: Profil ▸ Pengaturan ▸ Log Aktivitas (Admin).'])
render(page('Log Aktivitas','Riwayat siapa mengubah status lunas, absensi, role, dan penghapusan data • khusus Admin',[s1,s2,s3,s4,s5,s6,R_]),'/home/claude/work/26_log_aktivitas.jpg','26_log_aktivitas')
